contract InvMutTest {
    C c;

    uint256 constant CHECK_ACCESS_SEL = uint256(uint32(IAccessControl.checkAccess.selector));

    constructor(C _c) {
        c = _c;
    }

    fallback() external payable {
        bytes4 sel;
        assembly {
            sel := shr(224, calldataload(0))
        }
        assembly {
            mstore(0, 0)
            if eq(sel, CHECK_ACCESS_SEL) {
                mstore(0, 1)
            }
            return(0, 32)
        }
    }

    receive() external payable {}

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1, uint256 maxM, uint256 minM, uint256 r) public {
        require(kink >= 1 && kink < 1e27);

        c.initialize(address(this));

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({
            kink: kink,
            slope0: slope0,
            slope1: slope1
        });
        c.setSlopes(asset, slopes);
        c.setLimits(maxM, minM, r);

        // First rate() call: stored index is 0 and the (mocked) vault index is 0,
        // so utilization is 0. The interest rate must therefore be 0.
        uint256 rt = c.rate(address(this), asset);

        assert(rt == 0);
    }
}

