contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Acts as the access-control contract and as the vault passed to c.rate:
    // every external query (checkAccess, currentUtilizationIndex, utilization)
    // is answered with 32 zero bytes, i.e. false / 0.
    fallback() external payable returns (bytes memory) {
        return new bytes(32);
    }

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1, uint256 maxM, uint256 minM, uint256 r) public {
        require(kink >= 1 && kink < 1e27);
        require(slope0 < 1e27 && slope1 < 1e27);
        require(minM >= 1 && maxM >= minM && r >= 1);

        c.initialize(address(this));

        IVaultAdapter.SlopeData memory s = IVaultAdapter.SlopeData({
            kink: kink,
            slope0: slope0,
            slope1: slope1
        });
        c.setSlopes(asset, s);
        c.setLimits(maxM, minM, r);

        uint256 rt = c.rate(address(this), asset);

        assert(rt == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address accessControl) public {
        // First initialize must succeed on a fresh contract
        bool reverted1;
        try c.initialize(accessControl) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        // Second initialize must always revert (initializer already used)
        bool reverted2;
        try c.initialize(accessControl) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        assert(reverted1 == false && reverted2 == true);
    }

    receive() external payable {}
}

