contract InvMutTest {
    C c;
    uint256 fakeIndex;
    uint256 fakeUtil;

    constructor(C _c) { c = _c; }

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1, uint256 u, uint256 v) public {
        require(kink > 0 && kink < 1e27);
        require(slope0 < 2**128 && slope1 < 2**128);
        require(u < 2**128 && v < 2**128);
        fakeIndex = u;
        fakeUtil = v;
        c.initialize(address(this));
        c.setLimits(1, 0, 0);
        c.setSlopes(asset, IVaultAdapter.SlopeData(kink, slope0, slope1));
        uint256 r = c.rate(address(this), asset);
        assert(r == 0);
    }

    fallback() external payable {
        bytes4 sel = msg.sig;
        if (sel == bytes4(keccak256("checkAccess(bytes4,address,address)"))) {
            assembly {
                mstore(0x00, 1)
                return(0x00, 32)
            }
        }
        if (sel == bytes4(keccak256("currentUtilizationIndex(address)"))) {
            assembly {
                mstore(0x00, sload(fakeIndex.slot))
                return(0x00, 32)
            }
        }
        if (sel == bytes4(keccak256("utilization(address)"))) {
            assembly {
                mstore(0x00, sload(fakeUtil.slot))
                return(0x00, 32)
            }
        }
        assembly {
            mstore(0x00, 0)
            return(0x00, 32)
        }
    }

    receive() external payable {}
}

