contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        // initialize the adapter with this contract as access control:
        // our fallback below answers any checkAccess(...) with `true`.
        c.initialize(address(this));

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({
            kink: kink,
            slope0: slope0,
            slope1: slope1
        });

        bool reverted;
        try c.setSlopes(asset, slopes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == (kink == 0 || kink >= 1e27));
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        // grants access for every selector: encode a bool `true` return value
        return abi.encodePacked(bytes32(uint256(1)));
    }

    receive() external payable {}
}

